public class Main {
    static java.util.List<Integer> partitionLabelsBrute(String s) {
        int n = s.length();
        java.util.List<Integer> result = new java.util.ArrayList<>();
        int start = 0;
        while (start < n) {
            int end = start;
            for (int i = start; i <= end; i++) {
                int lastOccurrence = s.lastIndexOf(s.charAt(i));    // scan for the last occurrence, repeatedly
                end = Math.max(end, lastOccurrence);
            }
            result.add(end - start + 1);
            start = end + 1;
        }
        return result;
    }
}

