vector<int> partitionLabelsBrute(string s) {
    int n = s.size();
    vector<int> result;
    int start = 0;
    while (start < n) {
        int end = start;
        for (int i = start; i <= end; i++) {
            int lastOccurrence = s.rfind(s[i]);                      // scan for the last occurrence, repeatedly
            end = max(end, lastOccurrence);
        }
        result.push_back(end - start + 1);
        start = end + 1;
    }
    return result;
}

