import java.util.*;

public class Main {
    static List<Integer> partitionLabels(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;   // precompute, once
        List<Integer> result = new ArrayList<>();
        int start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            end = Math.max(end, last[s.charAt(i) - 'a']);                    // extend to cover last occurrence
            if (i == end) {                                                    // safe to close here
                result.add(end - start + 1);
                start = i + 1;
            }
        }
        return result;
    }
}

